function duration(s){s=Math.max(0,Math.ceil(s));if(s>=86400)return `${num(s/3600,0)} uur`;if(s>=3600)return `${Math.floor(s/3600)}u ${Math.floor(s%3600/60)}m`;if(s>=60)return `${Math.floor(s/60)}m ${s%60}s`;return s+'s';}
function timer(s){s=Math.max(0,Math.ceil(s));const h=Math.floor(s/3600),m=Math.floor(s%3600/60),sec=s%60;return h?`${h}:${String(m).padStart(2,'0')}:${String(sec).padStart(2,'0')}`:`${m}:${String(sec).padStart(2,'0')}`;}
const amount=(id,n)=>id==='feed'&&n>=1000?num(n/1000,1)+' kg':num(n,n<10?1:0)+' '+(SUPPLIES.find(x=>x.id===id)?.unit||'st');
const gear=id=>GEAR.find(x=>x.id===id),fish=id=>SPECIES.find(x=>x.id===id),water=id=>WATERS.find(x=>x.id===id),supply=id=>SUPPLIES.find(x=>x.id===id);
