 if(b.dataset.journalBulk){const action=b.dataset.journalBulk,rows=game.sessionRows(currentJournalId()).filter(f=>f.available&&(action!=='stock'||canStockSpecies(fish(f.species))));if(rows.length)act(game.chooseCatches(rows.map(f=>f.id),action));return;}
 if(b.dataset.strike!==undefined){strikeRod(Number(b.dataset.strike));return;}
