function applyPresetToSlot(id,slot){
 const resolved=game.resolveRodPreset(id);if(!act(resolved))return false;
 const rods=draft.rods.filter((r,i)=>(r.slot??i)!==slot);rods.push({...resolved.rod,slot,sourcePresetId:resolved.preset.id});rods.sort((a,b)=>a.slot-b.slot);
 const error=game.validateLoadout({...draft,rods});if(error){toast(error,'error');render();return false;}
 draft.rods=rods;assemblyDraft=assemblyDraftFrom(resolved.preset);selectedRodSlot=slot;selectedRodPreset=resolved.preset.id;appliedRodPreset=resolved.preset.id;rodPresetName=resolved.preset.name;previewBites.clear();render();return true;
}
function safeLoadout(id){return game.state.loadouts.find(l=>l.id===id)||game.loadout;}
document.addEventListener('change',event=>{
 const e=event.target,id=e.id;
 if(id==='assembly-style'){const name=assemblyDraft.name,id=assemblyDraft.id;assemblyDraft={...newAssemblyDraft(e.value),name,id};render();return;}
 if(e.dataset.assemblyField){const field=e.dataset.assemblyField;if(PARTS.includes(field)){assemblyDraft.items[field]=e.value||null;const item=game.state.tackleItems.find(i=>i.id===e.value);if(item)assemblyDraft.rod[field]=item.gearId;else if(field==='indicator')assemblyDraft.rod[field]=null;}else{assemblyDraft.rod[field]=e.value||null;if(field==='combo'){const combo=COMBOS.find(c=>c.id===e.value);if(combo?.requires&&!combo.requires.includes(assemblyDraft.rod.bait))assemblyDraft.rod.bait=combo.requires[0];}}render();return;}
 if(e.matches('[data-language-select]')){act(game.setLanguage(e.value));return;}
 if(id==='loadout-preset-select'){if(!e.value)return;draft=clone(safeLoadout(e.value));resetRodSelection();act(game.selectLoadout(e.value));return;}
 if(id==='rod-preset-select'){selectedRodPreset=e.value||null;render();return;}
 if(e.dataset.slotRodPreset!==undefined){if(e.value)applyPresetToSlot(e.value,Number(e.dataset.slotRodPreset));return;}
 if(e.hasAttribute('data-catch-sort')||e.hasAttribute('data-catch-sort-direction')){if(e.hasAttribute('data-catch-sort'))catchSort=e.value;else catchDirection=e.value;if(page==='home'){homeCatchSignature=null;refreshHomeCatches();translateGameUI($('#session-catches'));$(e.hasAttribute('data-catch-sort')?'[data-catch-sort]':'[data-catch-sort-direction]')?.focus({preventScroll:true});}else render();return;}
 if(id==='journal-select'){journalSelection=e.value;catchLimit=50;render();return;}
 if(e.dataset.catchChoice){const chosen=e.value||'pending';if(!act(game.chooseCatches([e.dataset.catchChoice],chosen)))e.value=choiceValue(game.sessionRows(currentJournalId()).find(f=>f.id===e.dataset.catchChoice)?.choice);return;}
 if(id==='forecast-source'){forecastSource=e.value;forecastRodSelection='all';refreshForecast();return;}
 if(id==='forecast-rod'){forecastRodSelection=e.value;refreshForecast();return;}
 if(id==='plan-water'){act(game.selectWater(e.value));return;}
 if(id==='plan-loadout'){act(game.selectLoadout(e.value));return;}
 if(id==='plan-duration'){setSessionDuration(e.value);return;}
 if(id==='plan-reserve'){act(game.setPlan({...game.state.plan,reserve:Number(e.value)}));return;}
 if(id==='shop-style'){shopStyle=e.value;render();return;}
 if(id==='shop-packs'){shopPacks=Math.max(1,Math.min(100,Math.floor(Number(e.value)||1)));render();return;}
 if(id==='gear-qty'){gearQty=Math.max(1,Math.min(6,Math.floor(Number(e.value)||1)));render();return;}
 if(id==='craft-qty'){craftQty=Math.max(1,Math.min(game.maxBatch,Math.floor(Number(e.value)||1)));render();return;}
 if(e.dataset.rodIndex!==undefined){const r=draft.rods[Number(e.dataset.rodIndex)],field=e.dataset.rodField;if(field==='style')draft.rods[Number(e.dataset.rodIndex)]={...starterRod(e.value),slot:r.slot??Number(e.dataset.rodIndex)};else{r[field]=e.value||null;if(field==='combo'){const combo=COMBOS.find(c=>c.id===e.value);if(combo?.requires&&!combo.requires.includes(r.bait))r.bait=combo.requires[0];}}render();return;}
 if(e.dataset.setting){act(game.setSetting(e.dataset.setting,e.checked));return;}
});
