$('#save-file').addEventListener('change',async event=>{const file=event.target.files?.[0];if(!file)return;if(file.size>64*1024*1024){toast('Dit bestand is te groot voor een spelopslag.','error');return;}const text=await file.text();ask('Opgeslagen imperium laden?','<p>Dit vervangt je huidige spel door de inhoud van het geselecteerde opslagbestand. Download eerst een kopie als je de huidige voortgang wilt bewaren.</p>','Opslag laden',()=>{if(act(game.importSave(text))){draft=null;assemblyDraft=null;render();if(game.welcome)showOffline(game.welcome);}});event.target.value='';});
