 if(event.type==='selection'){const root=$('#settlement-summary');if(root){root.innerHTML=settlementSummary(game,currentJournalId());const choices=new Map(game.sessionRows(currentJournalId()).map(f=>[f.id,f.choice]));$$('[data-catch-choice]').forEach(el=>{el.value=choiceValue(choices.get(el.dataset.catchChoice));el.closest('tr').dataset.choice=el.value;});translateGameUI(root);}return;}
